using System.Security.Claims;using DBM.POS.Domain.Entities;using DBM.POS.Infrastructure.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace DBM.POS.API.Controllers;
[ApiController,Authorize,Route("api/expenses")]
public class ExpenseController:ControllerBase{private readonly POSDbContext _db;public ExpenseController(POSDbContext db)=>_db=db;private Guid C=>Guid.Parse(User.FindFirstValue("companyId")!);private Guid? U=>Guid.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier),out var id)?id:(Guid?)null;
[HttpGet]public async Task<IActionResult>Get([FromQuery]DateTime?from,[FromQuery]DateTime?to,[FromQuery]Guid?branchId){var q=_db.Expenses.AsNoTracking().Where(x=>x.CompanyId==C);if(from.HasValue)q=q.Where(x=>x.ExpenseDate>=from);if(to.HasValue)q=q.Where(x=>x.ExpenseDate<to.Value.Date.AddDays(1));if(branchId.HasValue)q=q.Where(x=>x.BranchId==branchId);return Ok(await q.OrderByDescending(x=>x.ExpenseDate).ToListAsync());}
[HttpPost]public async Task<IActionResult>Create(RequestDto r){if(r.Amount<=0)return BadRequest(new{message="Amount must be greater than zero."});var no=string.IsNullOrWhiteSpace(r.ExpenseNo)?$"EXP-{DateTime.UtcNow:yyyyMMddHHmmssfff}":r.ExpenseNo;if(await _db.Expenses.AnyAsync(x=>x.CompanyId==C&&x.ExpenseNo==no))return Conflict(new{message="Expense number exists."});var e=new Expense{CompanyId=C,BranchId=r.BranchId,ExpenseNo=no,ExpenseDate=r.ExpenseDate??DateTime.UtcNow,Category=r.Category,Description=r.Description,Amount=r.Amount,PaymentMethod=r.PaymentMethod,ReferenceNo=r.ReferenceNo,UserId=U};_db.Expenses.Add(e);_db.CashTransactions.Add(new CashTransaction{CompanyId=C,BranchId=r.BranchId,TransactionType="Expense",Amount=r.Amount,PaymentMethod=r.PaymentMethod,ReferenceNo=no,Description=r.Description,UserId=U});await _db.SaveChangesAsync();return Ok(e);}
public record RequestDto(Guid BranchId,string Category,decimal Amount,string PaymentMethod="Cash",string? ExpenseNo=null,string? Description=null,string? ReferenceNo=null,DateTime? ExpenseDate=null);}
